// Maps upstream docs.netbird.io URLs used in UI links to embedded /docs
// paths for pages imported from netbirdio/docs. Generated by docs:build.
import generated from "@/generated/docs-links.json";

const MAP: Record<string, string> = {
  ...generated,
  // legacy /how-to aliases used throughout the UI
  "https://docs.netbird.io/how-to/manage-network-access": "/docs/upstream/manage-network-access",
  "https://docs.netbird.io/how-to/networks": "/docs/upstream/networks",
  "https://docs.netbird.io/how-to/manage-posture-checks": "/docs/upstream/posture-checks",
  "https://docs.netbird.io/how-to/register-machines-using-setup-keys": "/docs/upstream/register-machines-using-setup-keys",
  "https://docs.netbird.io/how-to/manage-dns-in-your-network": "/docs/upstream/dns",
  "https://docs.netbird.io/how-to/getting-started": "/docs/getting-started/quickstart-podman",
};

// docsLink returns the internal /docs path when the upstream URL is mapped,
// or the original URL otherwise. Anchors and queries are preserved.
export function docsLink(url: string): string {
  const clean = url.replace(/\/+$/, "");
  const m = clean.match(/^(https:\/\/docs\.netbird\.io\/[^?#]*)([?#].*)?$/);
  if (!m) return url;
  const hit = MAP[m[1]];
  return hit ? hit + (m[2] ?? "") : url;
}

export function isDocsInternal(url: string): boolean {
  return url.startsWith("/docs");
}
